"""Shipped-bundle backend for the whole-model decode megakernel.

This is the PRODUCTION consume path: it runs an entire model's decode step in one
persistent CUDA launch from artifacts BAKED INTO THE WHEEL -- with no ``mkl`` present.
``mkl`` is a BUILD-time dependency only (it emits the ``.so`` / cubin / tape / manifest
via ``scripts/precompile/families/whole_model.py``); at runtime this module reaches only
into ``kestrel_kernels`` (the AOT runtime + the shipped bundle) plus the already-loaded
kestrel ``text`` model whose weights it stacks. Nothing here imports ``mkl``.

What it does, mirroring the MD2/MD3 development session builders byte-for-byte so the shipped
decode == the dev backend == native:

  1. Resolve the AOT ``.so`` for this ``(variant, arch)`` via ``cute_aot_runtime.AotFamily``
     (shipped ``.kstlc`` section, or a loose JIT ``.so`` on a source install).
  2. Load the instruction tape (``mInstr`` / ``mQlen``) + counter count from the baked
     manifest blobs (base64 int32), rebuild the gmem tape.
  3. Stack the engine's per-layer checkpoint weights into the selected whole-model layout. MD3's
     interleaved MoE-up slab remains engine-owned and zero-copy; MD2 supplies ordinary dense slabs.
  4. Allocate the persistent batch buffers once (the ``resid``..``lse_partial`` state, the
     qmma route tables, cos/sin/tau/current-position state) and wire the DIRECT
     paged-KV handles (the engine pool's per-layer int64 base tables + the live page table).
  5. Per decode step dispatch through the PREBUILT packed argument array (built once; only
     data ptrs + stream patched per step) -- no CUDA graph (the megakernel is ONE launch;
     ``input_pos`` / KV-length / active-batch are plain launch args).

The generated AOT header is the sole runtime ABI authority. Its ordered argument names and kinds are
recorded in the bundle manifest; this backend supplies a complete name-to-value map and rejects any
missing, extra, reordered, or duplicate binding before launch. Model features such as FP8 KV and a
folded head add ordinary named arguments rather than positional runtime conventions.
"""
from __future__ import annotations

import base64
import ctypes
import json
from pathlib import Path
from typing import Optional

import torch

from kestrel_kernels.arch import get_cuda_arch
from kestrel_kernels.cute_aot_runtime import AotFamily, get_raw_stream

WHOLE_MODEL_FAMILY = "whole_model"
BATCH_TILE = 8
_DTYPE = torch.bfloat16

# ENGINE KV-RESERVATION CONTRACT: the engine reserves KV pages for the WHOLE request at ADMISSION,
# not per decode step. The scheduler computes ``reserve_length = target_length - skip_positions`` and
# gates scheduling on it (``scheduler.py``); ``kv_cache.reserve()`` then allocates the physical pages
# and writes them into the page-table row, growing ``page_table.capacity[batch_idx]`` to cover the
# request's target. Decode never runs past ``target_length``. The bundle consumes that global table
# directly with the engine's compact-row selector and current position; it does not reserve, commit,
# gather, or shadow page-table state.


# ======================================================================================
# Ported weight-stacking / KV / RoPE-TAU helpers (pure torch; NO mkl).
# ======================================================================================
def _stack_md2_weights(text, *, device) -> dict:
    """Stack production MD2 decoder weights into the dense whole-model VM layout."""
    blocks = text["blocks"]

    def st(xs):
        return torch.stack(xs, dim=0).contiguous()

    return dict(
        gamma=st([block["ln"].weight.detach().float() for block in blocks]),
        beta=st([block["ln"].bias.detach().float() for block in blocks]),
        Wqkv=st([block["attn"]["qkv"].weight.detach().to(_DTYPE) for block in blocks]),
        qkv_bias=st([block["attn"]["qkv"].bias.detach().float() for block in blocks]),
        Wfc1=st([block["mlp"]["fc1"].weight.detach().to(_DTYPE) for block in blocks]),
        b1=st([block["mlp"]["fc1"].bias.detach().float() for block in blocks]),
        Wo=st([block["attn"]["proj"].weight.detach().to(_DTYPE) for block in blocks]),
        o_bias=st([block["attn"]["proj"].bias.detach().float() for block in blocks]),
        Wfc2=st([block["mlp"]["fc2"].weight.detach().to(_DTYPE) for block in blocks]),
        b2=st([block["mlp"]["fc2"].bias.detach().float() for block in blocks]),
    )


def _engine_moe_up_slabs(text, tc):
    """THE megakernel<->engine MoE up-weight slab contract (kestrel#121 +
    ``weights.build_md3_moe_up_slab``); mirrors ``mkl.megakernel.session.md3._engine_moe_up_slabs``.

    The engine stores the MD3 FP8 MoE up weight/scale ONCE, in a stacked ``[NL, E, 2I, H]`` uint8
    slab (+ ``[NL, E, 2I]`` f32 scale slab) in the 8-row gate/up interleave, and points each MoE
    layer's ``up_experts.weight``/``scale`` at a layer-view. That is byte-for-byte the layout the
    batch VM consumes (``moe_up_interleaved8=True``, global ``FIELD_LAYER`` indexing), so the AOT
    decode session uses the slab DIRECTLY -- zero copy, no per-session stack. REQUIRED (the
    version pin guarantees the pairing); raises if the slab is absent or the views do not alias it
    at the ``[NL]`` stride, with no private-stack fallback."""
    H = tc.dim
    E = tc.moe.num_experts
    I = tc.moe.expert_inner_dim
    NL = tc.n_layers
    up_w_slab = getattr(text, "moe_up_w_slab", None)
    up_scale_slab = getattr(text, "moe_up_scale_slab", None)
    if up_w_slab is None or up_scale_slab is None:
        raise RuntimeError(
            "engine did not build the MoE up-weight slab (text.moe_up_w_slab); the megakernel "
            "REQUIRES the engine-owned interleaved slab. Update kestrel to the version paired with "
            "these kernels (kestrel#121 / weights.build_md3_moe_up_slab).")
    if tuple(up_w_slab.shape) != (NL, E, 2 * I, H) or up_w_slab.dtype != torch.uint8:
        raise RuntimeError(
            f"engine MoE up-weight slab {tuple(up_w_slab.shape)}/{up_w_slab.dtype} != expected "
            f"{(NL, E, 2 * I, H)}/uint8")
    if tuple(up_scale_slab.shape) != (NL, E, 2 * I) or up_scale_slab.dtype != torch.float32:
        raise RuntimeError(
            f"engine MoE up-scale slab {tuple(up_scale_slab.shape)}/{up_scale_slab.dtype} != "
            f"expected {(NL, E, 2 * I)}/float32")
    w_base = up_w_slab.untyped_storage().data_ptr()
    s_base = up_scale_slab.untyped_storage().data_ptr()
    w_stride = E * 2 * I * H
    s_stride = E * 2 * I
    for li, blk in enumerate(text.blocks):
        if not hasattr(blk.mlp, "router"):
            continue
        up = blk.mlp["mlp"].up_experts
        w, s = up.weight, up.scale
        if (w.untyped_storage().data_ptr() != w_base or w.storage_offset() != li * w_stride
                or not w.is_contiguous() or tuple(w.shape) != (E, 2 * I, H)):
            raise RuntimeError(
                f"MoE layer {li} up_experts.weight does not alias the engine up-weight slab at the "
                f"[NL] offset -- the slab contract is broken.")
        if (s.untyped_storage().data_ptr() != s_base or s.storage_offset() != li * s_stride
                or not s.is_contiguous() or tuple(s.shape) != (E, 2 * I)):
            raise RuntimeError(
                f"MoE layer {li} up_experts.scale does not alias the engine up-scale slab at the "
                f"[NL] offset -- the slab contract is broken.")
    return up_w_slab, up_scale_slab


def _stack_md3_weights(text, tc, *, device) -> dict:
    """Stack production MD3 decoder weights into the whole-model MD3 batch-VM layout.

    The MoE up weight/scale is the engine-owned interleaved-by-8 slab (:func:`_engine_moe_up_slabs`)
    used byte-for-byte, zero copy (``moe_up_interleaved8=True``); everything else is stacked per
    layer with zero rows for the other branch."""
    H, FF = tc.dim, tc.ff_dim
    E = tc.moe.num_experts
    I = tc.moe.expert_inner_dim
    qkv_out = H + 2 * tc.n_kv_heads * (H // tc.n_heads)
    dev, dt = device, _DTYPE

    # THE engine-owned up slab (asserts each MoE layer's view aliases it at the [NL] stride).
    up_w_slab, up_scale_slab = _engine_moe_up_slabs(text, tc)

    def st(xs):
        return torch.stack(xs, dim=0).contiguous()

    zeros_fc1 = torch.zeros(FF, H, device=dev, dtype=dt)
    zeros_b1 = torch.zeros(FF, device=dev, dtype=torch.float32)
    zeros_fc2 = torch.zeros(H, FF, device=dev, dtype=dt)
    zeros_b2 = torch.zeros(H, device=dev, dtype=torch.float32)
    zeros_gate_w = torch.zeros(E, H, device=dev, dtype=dt)
    zeros_gate_b = torch.zeros(E, device=dev, dtype=torch.float32)
    zeros_down_w = torch.zeros(E, H, I, device=dev, dtype=torch.uint8)
    zeros_down_scale = torch.zeros(E, H, device=dev, dtype=torch.float32)

    Wfc1, b1, Wfc2, b2 = [], [], [], []
    gate_w, gate_b, down_w, down_scale = [], [], [], []
    for blk in text.blocks:
        is_moe = hasattr(blk.mlp, "router")
        if is_moe:
            fused = blk.mlp["mlp"]
            Wfc1.append(zeros_fc1); b1.append(zeros_b1)
            Wfc2.append(zeros_fc2); b2.append(zeros_b2)
            gate_w.append(blk.mlp["router"].weight.detach().to(dt))
            gate_b.append(blk.mlp["router"].bias.detach().float())
            # up weight/scale come from the engine slab (up_w_slab/up_scale_slab), not stacked here.
            down_w.append(fused.down_experts.weight.detach().view(torch.uint8))
            down_scale.append(fused.down_experts.scale.detach().float())
        else:
            Wfc1.append(blk.mlp["fc1"].weight.detach().to(dt))
            b1.append(blk.mlp["fc1"].bias.detach().float())
            Wfc2.append(blk.mlp["fc2"].weight.detach().to(dt))
            b2.append(blk.mlp["fc2"].bias.detach().float())
            gate_w.append(zeros_gate_w); gate_b.append(zeros_gate_b)
            down_w.append(zeros_down_w); down_scale.append(zeros_down_scale)

    return dict(
        gamma=st([blk.ln.weight.detach().float() for blk in text.blocks]),
        beta=st([blk.ln.bias.detach().float() for blk in text.blocks]),
        Wqkv=st([blk.attn.qkv.weight.detach().to(dt) for blk in text.blocks]),
        qkv_bias=st([blk.attn.qkv.bias.detach().float() for blk in text.blocks]),
        zero_bias=torch.zeros(qkv_out, device=dev, dtype=torch.float32),
        Wqwv=st([blk.attn.tau["wqwv"].detach().to(dt) for blk in text.blocks]),
        Wfc1=st(Wfc1), b1=st(b1),
        Wo=st([blk.attn.proj.weight.detach().to(dt) for blk in text.blocks]),
        o_bias=st([blk.attn.proj.bias.detach().float() for blk in text.blocks]),
        Wfc2=st(Wfc2), b2=st(b2),
        gate_w=st(gate_w), gate_b=st(gate_b),
        up_w=up_w_slab, up_scale=up_scale_slab,
        down_w=st(down_w), down_scale=st(down_scale),
    )


def _cossin_table(text, rot_dim):
    cache = text.cos_sin_cache.float()
    half = rot_dim // 2
    cos = torch.cat([cache[:, :half], cache[:, :half]], dim=1).contiguous().float()
    sin = torch.cat([cache[:, half:half + half], cache[:, half:half + half]], dim=1).contiguous().float()
    return cos, sin


def _tau_pos_table(text):
    return torch.stack(
        [blk.attn._tau_pos_table.detach().float() for blk in text.blocks], dim=0).contiguous()


def _qmma_route_capacity(active_batch, *, top_k, num_experts, block_m=16):
    assignments = int(active_batch) * int(top_k)
    if assignments <= 0:
        return 0, 0
    active_experts = min(int(num_experts), assignments)
    max_blocks = active_experts + (assignments - active_experts) // int(block_m)
    return assignments, max_blocks


# ======================================================================================
# Bundle metadata (tape + counters) -- baked by the build, read WITHOUT mkl.
# ======================================================================================
def _sidecar_path(bundle_dir: Path, variant_key: str, arch: str) -> Path:
    return bundle_dir / f"{variant_key}_{arch}.megakernel.json"


def _iter_candidate_metas(family: AotFamily, arch: str):
    """Yield ``(variant_key, meta)`` for every baked whole-model variant discoverable WITHOUT mkl:
    the shipped ``.kstlc`` family manifest (``variants[key]``) first, then loose sidecars next to the
    ``.so`` (source-install / dev build). ``meta`` is the ``manifest_variant`` metadata dict (carries
    the recorded ``spec`` + the ``tape`` the launch rebuilds). This is how runtime selection ENUMERATES
    candidates to match the caller's requested spec against -- there is no key computed from literals,
    so the ``kv_capacity`` / ``vocab`` policy constants live ONLY in mkl's spec source, not here."""
    seen: set[str] = set()
    packed_keys = tuple(dict.fromkeys(
        str(key)
        for manifest in family._load_manifests()
        for key in (manifest.get("variants") or {})
    ))
    for key in packed_keys:
        # Resolve metadata through the same archive-priority and host-ABI path
        # that AotFamily.resolve() uses for the wrapper. An overlay may carry
        # this key but lack a viable host wrapper; independently deduplicating
        # manifest dictionaries would then pair its tape with a base archive's
        # executable.
        resolved = next(family._iter_shipped_entries(key, arch), None)
        if resolved is None:
            # Packed tape/catalog metadata is also the source of truth for a
            # reused loose wrapper or a source-install JIT build. Preserve the
            # highest-priority complete entry when no packaged wrapper is
            # viable so AotFamily.resolve() can reach those fallback paths.
            variant = next((
                candidate
                for manifest in family._load_manifests()
                for candidate_key, candidate in (
                    manifest.get("variants") or {}
                ).items()
                if (
                    str(candidate_key) == key
                    and candidate
                    and candidate.get("tape")
                )
            ), None)
        else:
            variant, _aot_meta, _so_bytes = resolved
        if not variant or not variant.get("tape"):
            continue
        meta = dict(variant.get("variant") or {})
        meta["tape"] = variant["tape"]
        seen.add(key)
        yield key, meta
    for sidecar in sorted(family.bundle_dir.glob(f"*_{arch}.megakernel.json")):
        key = sidecar.name[: -len(f"_{arch}.megakernel.json")]
        if key in seen:
            continue
        try:
            yield key, json.loads(sidecar.read_text())
        except (OSError, ValueError):
            continue


def _tape_to_device(tape_meta: dict, device) -> tuple:
    """Rebuild (mInstr, mQlen) gmem int32 tensors + num_counters from the base64 blobs."""
    instr_shape = tuple(tape_meta["instr_shape"])
    qlen_shape = tuple(tape_meta["qlen_shape"])
    instr = torch.frombuffer(
        bytearray(base64.b64decode(tape_meta["instr_b64"])), dtype=torch.int32
    ).reshape(instr_shape).clone().to(device)
    qlen = torch.frombuffer(
        bytearray(base64.b64decode(tape_meta["qlen_b64"])), dtype=torch.int32
    ).reshape(qlen_shape).clone().to(device)
    return instr.contiguous(), qlen.contiguous(), int(tape_meta["num_counters"])


# ======================================================================================
# The decode session.
# ======================================================================================
class MegakernelNotEligible(RuntimeError):
    pass


class _BundleSession:
    """Whole-model decode over a shipped AOT bundle with a named compiled ABI."""

    def __init__(self, *, bundle, bindings, arg_abi, memref_abi, stream_c,
                 device_index, num_ctas, batch_size, n_layers, hidden,
                 resid, ctr, x0, input_pos,
                 page_table, batch_idx, kv_cap, n_kv_heads, head_dim,
                 logits=None, token=None):
        self._bundle = bundle
        self._stream_c = stream_c
        self._device_index = device_index
        self.num_ctas = int(num_ctas)
        self.batch_size = int(batch_size)
        self._n_layers = int(n_layers)
        self._hidden = int(hidden)
        self._resid, self._ctr, self._x0 = resid, ctr, x0
        self._input_pos = input_pos
        self._page_table = page_table
        self._batch_idx = batch_idx
        self._kv_cap = int(kv_cap)
        self._n_kv_heads, self._head_dim = n_kv_heads, head_dim
        # TAIL-FOLD (Stage A/B): the in-kernel lm_head logits buffer + device-argmax token slot (None
        # on a host-lm_head build). ``decode`` returns the logits directly when the head is folded (the
        # engine boundary moves from "kernel returns hidden" to "kernel returns logits"); ``decode_token``
        # returns the device greedy token the ARGMAX op wrote (read async, no host argmax + .item()).
        # Mirrors mkl.megakernel.decode_bridge.Md3MegakernelDecode's ``_logits`` / ``_token``.
        self._logits = logits
        self._token = token
        self.direct_paged_kv = True
        entries = tuple(arg_abi or ())
        if not entries:
            raise RuntimeError("megakernel bundle is missing its named AOT argument ABI")
        if any(set(entry) != {"name", "kind"} for entry in entries):
            raise RuntimeError(f"malformed megakernel arg ABI: {entries}")
        names = tuple(entry["name"] for entry in entries)
        if len(names) != len(set(names)):
            raise RuntimeError(f"duplicate megakernel argument names: {names}")
        kinds = tuple(entry["kind"] for entry in entries)
        if kinds != tuple(bundle.arg_kinds):
            raise RuntimeError(
                f"megakernel argument-kind mismatch: manifest={kinds}, compiled={bundle.arg_kinds}")
        self._memref_names = tuple(
            entry["name"] for entry in entries if entry["kind"] == "memref")
        if self._memref_names != tuple(memref_abi or ()):
            raise RuntimeError(
                f"megakernel memref order mismatch: arg_abi={self._memref_names}, "
                f"memref_abi={tuple(memref_abi or ())}")
        self._scalar_names = tuple(
            entry["name"] for entry in entries if entry["kind"] == "scalar")
        expected = set(self._memref_names) | set(self._scalar_names)
        supplied = set(bindings)
        if expected != supplied:
            raise RuntimeError(
                f"megakernel named binding mismatch: missing={sorted(expected - supplied)}, "
                f"extra={sorted(supplied - expected)}")
        self._bindings = dict(bindings)
        self._memrefs = [self._bindings[name] for name in self._memref_names]
        self._memref_positions = {
            name: index for index, name in enumerate(self._memref_names)}
        self._specs = bundle.memref_specs
        if len(self._specs) != len(self._memrefs):
            raise RuntimeError(
                f"megakernel memref count mismatch: bundle expects {len(self._specs)}, "
                f"backend supplies {len(self._memrefs)}")
        # PREBUILT PACKING. Every megakernel arg is a PERSISTENT buffer with a stable data ptr / shape /
        # stride, and the scalars (n_pages/kv_len/active_batch) are session constants, so the whole
        # argument array is built ONCE here; _launch patches only the data ptrs (cheap, robust to a
        # buffer swap) + the stream handle in place, then calls the ciface directly. This is the
        # AotInvokeState hot-launch pattern extended to the scalar args this variant carries
        # (AotInvokeState itself is scalar-free, so it is reproduced locally rather than reused).
        # NOTE: the "~1.5ms/step of ctypes packing dwarfs the kernel" premise is DISPROVEN by
        # measurement -- per-step packing is ~10us (53-struct build + packed void*[]), halved to ~5us
        # here, and the ~1.5ms/eager-step is the MEGAKERNEL itself (kernel-only wall ~= 1556us on
        # H100/sm90 B1). So this is a clean hot-path cleanup (build-once, no per-step allocation), NOT
        # a launch-latency win -- the host packing was always hidden behind the async kernel at B1. It
        # only starts to matter host-bound (batch / a much faster kernel).
        self._scalars_c = [
            ctypes.c_int32(int(self._bindings[name])) for name in self._scalar_names]
        self._structs = [spec.build(t) for spec, t in zip(self._specs, self._memrefs)]
        self._err_c = ctypes.c_int32(0)
        self._packed = bundle._packed_type()
        for slot, inst in zip(bundle._memref_arg_indices, self._structs):
            self._packed[slot] = ctypes.addressof(inst)
        for slot, sc in zip(bundle._scalar_arg_indices, self._scalars_c):
            self._packed[slot] = ctypes.addressof(sc)
        _stream_addr = ctypes.addressof(self._stream_c)
        for slot in bundle._stream_arg_indices:
            self._packed[slot] = _stream_addr
        self._packed[bundle._err_slot] = ctypes.addressof(self._err_c)
        self._packed_addr = ctypes.cast(self._packed, ctypes.c_void_p)

    @property
    def input_pos(self) -> torch.Tensor:
        if self._input_pos is None:
            raise RuntimeError("position rebind not enabled for this session")
        return self._input_pos

    @property
    def kv_capacity(self) -> int:
        """Maximum token position extent baked into this compiled session."""
        return self._kv_cap

    def _bind_step(self, step, batch_idx) -> None:
        if step is None:
            return
        emb = step.embed
        emb = emb[:, 0, :] if emb.dim() == 3 else emb
        self._x0[: self.batch_size].copy_(emb[: self.batch_size].to(self._x0.dtype))
        if step.position is None or batch_idx is None:
            raise RuntimeError("decode requires authoritative batch_idx and input_pos tensors")
        self._batch_idx = batch_idx
        self._input_pos = step.position
        for name, value in (("mBatchIdx", batch_idx), ("mInputPos", step.position)):
            try:
                index = self._memref_positions[name]
            except KeyError as exc:
                raise RuntimeError(f"megakernel ABI is missing mutable input {name!r}") from exc
            self._bindings[name] = value
            self._memrefs[index] = value

    def bind_runtime_tensors(self, tensors) -> None:
        raise MegakernelNotEligible(
            "this shipped bundle has no dynamic contraction capacity; build the capacity artifact "
            "or use the development backend")

    def _launch(self) -> None:
        self._ctr.zero_()
        self._resid.zero_()
        self._resid[0, : self.batch_size] = self._x0[: self.batch_size]
        aot = self._bundle.aot
        aot._ensure_device(self._device_index)
        # Fast path: patch only the per-step-mutable fields of the prebuilt packed argument array
        # (data ptrs + stream), then dispatch. NO per-step ctypes struct/array allocation.
        for spec, inst, t in zip(self._specs, self._structs, self._memrefs):
            inst.data = t.data_ptr()
        self._stream_c.value = get_raw_stream(self._device_index)
        self._err_c.value = 0
        self._bundle._invoke_packed(self._packed_addr, self._err_c)

    def decode(self, step=None, batch_idx=None) -> torch.Tensor:
        # The engine-owned selectors are rebound by name; the global page table is never gathered.
        self._bind_step(step, batch_idx)
        self._launch()
        # TAIL-FOLD (Stage A): the megakernel folded the lm_head -- return the logits ``[B, vocab]``
        # it wrote directly (host lm_head deleted). Mirrors mkl decode_bridge.decode. Falls back to the
        # decoder hidden ``[B, 1, H]`` on a host-lm_head build (vocab==0).
        if self._logits is not None:
            return self._logits[: self.batch_size]
        return self._resid[self._n_layers % 2, : self.batch_size].view(
            self.batch_size, 1, self._hidden)

    def decode_token(self, step=None, batch_idx=None) -> torch.Tensor:
        """TAIL-FOLD (Stage B2): run one decode token and return the DEVICE greedy token slot
        ``[B]`` int32 the megakernel's in-kernel argmax wrote -- NOT the logits. The engine reads it
        async (no host argmax + ``.item()`` on the decode critical path). Mirrors
        mkl.megakernel.decode_bridge.Md3MegakernelDecode.decode_token; raises on a host-lm_head build
        (no device token slot)."""
        if self._token is None:
            raise RuntimeError(
                "decode_token needs the in-kernel lm_head + argmax (folded-head bundle); this "
                "session has no device token slot (host lm_head path). Use decode() for logits.")
        self._bind_step(step, batch_idx)
        self._launch()
        return self._token[: self.batch_size]

    __call__ = decode


# ======================================================================================
# Build entry.
# ======================================================================================
def _jit_compile_fn_factory(variant):
    """Source-install JIT fallback: build the AOT ``.so`` from the mkl-owned compile target.
    Imported lazily so a masked-mkl host that already has a loose/shipped ``.so`` never
    touches mkl. On a serving host with no mkl and no ``.so``, AotFamily.resolve returns None
    (native fallback) before this is ever called.

    ``variant`` carries the opaque artifact key and the typed target SM count.
    ``make_compile_target`` needs the full ``WholeModelSpec``, so reconstruct it here by
    matching both fields against the mkl spec builders. Artifact-key formatting is not an ABI."""
    from mkl.megakernel.integration import (
        artifact_variant_key,
        get_tape,
        iter_model_specs,
        make_compile_target,
    )

    def compile_fn(arch: str):
        key = variant.variant_key
        num_sms = int(variant.num_sms)
        specs = iter_model_specs(
            num_sms=num_sms,
            gpu=torch.cuda.get_device_name(torch.cuda.current_device()),
        )
        matches = tuple(
            candidate for candidate in specs
            if key.startswith(f"{candidate.variant_key}_tape")
        )
        if len(matches) != 1:
            raise ValueError(
                "whole-model JIT fallback: artifact key must identify exactly one "
                f"mkl WholeModelSpec, got {len(matches)} for {key!r}")
        spec = matches[0]
        tape = get_tape(spec)
        exact_key = artifact_variant_key(spec, tape=tape)
        if exact_key != key:
            raise ValueError(
                "whole-model JIT fallback: selected spec emitted a different tape/program "
                f"identity: requested={key!r}, emitted={exact_key!r}")
        vm, fake_args = make_compile_target(spec)
        return (vm, *fake_args)

    return compile_fn


def _make_family() -> AotFamily:
    return AotFamily(WHOLE_MODEL_FAMILY, jit_compile_fn=_jit_compile_fn_factory)


class _VariantKey:
    def __init__(self, key: str, num_sms: int):
        self.variant_key = key
        self.num_sms = int(num_sms)


_SELECTION_CATALOG_SCHEMA = 1


def _runtime_spec_constraints(kind: str, tc, num_ctas: int, config) -> dict:
    """Semantic request facts supplied by the loaded trace/config, never by an artifact.

    Compiler-owned policy and pricing results (partitioning, physical specialization, KV format,
    engine arm, storage capacity, and ABI) are deliberately absent. The compiler-emitted selection
    catalog supplies those fields; the selected full spec is then compared to the candidate exactly.
    """
    constraints = {
        "kind": str(kind),
        "hidden": int(tc.dim),
        "inter": int(tc.ff_dim),
        "n_layers": int(tc.n_layers),
        "qkv_nh": int(tc.n_heads),
        "qkv_nkv": int(tc.n_kv_heads),
        "qkv_head_dim": int(tc.dim // tc.n_heads),
        "qkv_rot_dim": int(tc.dim // (2 * tc.n_heads)),
        "num_sms": int(num_ctas),
    }
    moe = getattr(tc, "moe", None)
    if moe is not None:
        cfg = lambda name, default: (
            getattr(config, name, default) if config is not None else default)
        constraints.update({
            "moe_num_experts": int(moe.num_experts),
            "moe_top_k": int(moe.experts_per_token),
            "moe_inter": int(moe.expert_inner_dim),
            "moe_start_layer": int(moe.start_layer),
            "stream_moe_down": bool(cfg("stream_moe_down", True)),
            "stream_moe_b": bool(cfg("stream_moe_b", False)),
            "qmma_num_stages": int(cfg("qmma_num_stages", 3)),
            "moe_lora_rank": int(cfg("moe_lora_rank", 0)),
        })
    return constraints


def _selection_catalog(family: AotFamily, candidates) -> tuple[dict, ...]:
    """Load compiler-emitted selector records, never reconstructing them from candidate specs."""
    records = []
    sidecar_catalogs = [
        meta for _, meta in candidates if meta.get("selection_catalog") is not None]

    # Explicit per-variant development sidecars are authoritative when present. Production has no
    # sidecars and uses the repacked compiler catalog without importing mkl.
    if sidecar_catalogs:
        manifests = sidecar_catalogs
    else:
        manifests = family._load_manifests()

    for manifest in manifests:
        catalog = manifest.get("selection_catalog")
        if catalog is None:
            continue
        if int(manifest.get("selection_catalog_schema", -1)) != _SELECTION_CATALOG_SCHEMA:
            raise ValueError("whole-model selection catalog has an unsupported schema")
        if not isinstance(catalog, list):
            raise ValueError("whole-model selection catalog must be a list")
        records.extend(catalog)
    unique = {}
    for record in records:
        if not isinstance(record, dict):
            raise ValueError("whole-model selection catalog record must be an object")
        required = {"arch", "variant_key", "request_extent_bindings", "spec"}
        if set(record) != required or not isinstance(record["spec"], dict):
            raise ValueError("malformed whole-model selection catalog record")
        canonical = json.dumps(record, sort_keys=True, separators=(",", ":"))
        unique[canonical] = record
    return tuple(unique[key] for key in sorted(unique))


def _select_requested_spec(
    catalog,
    *,
    arch: str,
    constraints: dict,
    static_extent_bindings,
) -> Optional[dict]:
    requested_extents = {
        str(symbol): int(extent)
        for symbol, extent in (static_extent_bindings or {}).items()
    }
    matches = []
    for record in catalog:
        if str(record["arch"]) != str(arch):
            continue
        spec = record["spec"]
        if any(spec.get(field) != value for field, value in constraints.items()):
            continue
        extents = {
            str(symbol): int(extent)
            for symbol, extent in record["request_extent_bindings"].items()
        }
        if extents != requested_extents:
            continue
        matches.append(record)
    # Zero matches means this runtime demand was not compiled. Multiple matches mean the compiler
    # emitted an ambiguous routing domain. Both are native/JIT fallback, never arbitrary selection.
    return matches[0] if len(matches) == 1 else None


def resolve_bundle(
    kind: str,
    tc,
    num_ctas: int,
    config=None,
    arch: Optional[str] = None,
    static_extent_bindings=None,
):
    """Resolve one exact compiler-selected artifact, or fail closed to native/JIT.

    ``kind`` is the compiler registry key supplied by the model-registration boundary. This resolver
    contains no model-name table and never overlays facts onto a candidate's baked spec.
    """
    arch = arch or get_cuda_arch()
    family = _make_family()
    candidates = tuple(_iter_candidate_metas(family, arch))
    requested = _select_requested_spec(
        _selection_catalog(family, candidates),
        arch=arch,
        constraints=_runtime_spec_constraints(kind, tc, int(num_ctas), config),
        static_extent_bindings=static_extent_bindings,
    )
    if requested is None:
        return None, None
    requested_key = str(requested["variant_key"])
    requested_spec = requested["spec"]
    for key, meta in candidates:
        baked = meta.get("spec")
        if key != requested_key or baked != requested_spec or not meta.get("tape"):
            continue
        bundle = family.resolve(_VariantKey(key, int(num_ctas)), arch)
        if bundle is not None:
            return bundle, meta
    return None, None


def bundle_available(kind: str, tc, num_ctas: int, config=None,
                     arch: Optional[str] = None, static_extent_bindings=None) -> bool:
    try:
        bundle, meta = resolve_bundle(
            kind, tc, num_ctas, config, arch,
            static_extent_bindings=static_extent_bindings)
    except Exception:
        return False
    return bundle is not None and meta is not None


def shipped_bundle_available(
    kind: str,
    num_ctas: int,
    *,
    arch: str,
    static_extent_bindings=None,
) -> bool:
    """Whether the compiler catalog selects one exact, host-compatible packed artifact.

    This is the native-graph suppression preflight. It reads only shipped metadata and calls
    ``resolve_shipped``; it never reuses a loose JIT wrapper, compiles, initializes CUDA, or launches.
    The compiler registry key plus request extent must be unique because the deployment gate has no
    model trace from which to disambiguate multiple compiler configurations.
    """
    try:
        family = _make_family()
        candidates = tuple(_iter_candidate_metas(family, arch))
        requested = _select_requested_spec(
            _selection_catalog(family, candidates),
            arch=str(arch),
            constraints={"kind": str(kind), "num_sms": int(num_ctas)},
            static_extent_bindings=static_extent_bindings,
        )
        if requested is None:
            return False
        key = str(requested["variant_key"])
        spec = requested["spec"]
        exact = [
            candidate_key for candidate_key, meta in candidates
            if candidate_key == key and meta.get("spec") == spec and meta.get("tape")
        ]
        if len(exact) != 1:
            return False
        return family.resolve_shipped(
            _VariantKey(key, int(num_ctas)), str(arch)) is not None
    except Exception:
        return False


def _build_md3_decode_session(text, tc, dec_embed0, page_table, batch_idx, *, input_pos=None,
                              compiler_kind: str, batch_bucket: int,
                              seqlen: int, num_ctas: int, config=None,
                              kv_capacity: Optional[int] = None, arch: Optional[str] = None):
    """Build the MD3 whole-model decode session from the shipped bundle whose baked spec matches the
    caller's ``config`` (see ``resolve_bundle``). Raises ``MegakernelNotEligible`` when no matching
    bundle fits (native / JIT fallback)."""
    # The engine builds with ``dec_embed0=None`` (it rebinds the embedding every step, so the
    # build-time embedding never reaches an output). Synthesize the zero placeholder from the
    # variant's shapes -- mirroring the dev path (mkl.megakernel.session.md3._build_megakernel_run)
    # -- so the rest of the build is unchanged. Device comes from ``batch_idx`` (a live device
    # tensor) since there is no embedding to read it from.
    if dec_embed0 is None:
        device = batch_idx.device
        dec_embed0 = torch.zeros(int(batch_bucket), 1, tc.dim, device=device, dtype=_DTYPE)
    else:
        device = dec_embed0.device
    device_index = int(device.index or 0)
    bundle, meta = resolve_bundle(
        compiler_kind, tc, int(num_ctas), config, arch,
        static_extent_bindings={"active_batch": int(batch_bucket)})
    if bundle is None or meta is None:
        raise MegakernelNotEligible("no shipped whole-model megakernel bundle for this device")

    H, NKV, NH = tc.dim, tc.n_kv_heads, tc.n_heads
    HD = H // NH
    ROT = H // (2 * NH)
    qkv_out = H + 2 * NKV * HD
    E, I, TOPK = tc.moe.num_experts, tc.moe.expert_inner_dim, tc.moe.experts_per_token
    NL = tc.n_layers
    batch_size = int(batch_bucket)
    history = int(seqlen) - 1
    NS = int(meta.get("num_splits", 1))
    # The KV/page-table buffer DEPTH is the variant's BAKED kv_capacity (compiled into the
    # kernel's KV tensormap + shapes -- a static KC). It is NOT the runtime `kv_capacity`
    # request: the shipped cubin is frozen at the baked depth, so a smaller buffer would make
    # the kernel index out of bounds. The runtime `kv_capacity` only bounds how far the decode
    # may advance (<= baked); the actual per-step scan length is driven by `input_pos`.
    kv_cap = int(meta.get("kv_capacity") or seqlen)
    if kv_cap < int(seqlen):
        # The prefill history exceeds the variant's baked KV depth: this sequence is beyond the
        # megakernel's bucket -> NATIVE fallback (non-fatal), not a hard error. (Ship policy: contexts
        # past the baked kv_capacity run native.)
        raise MegakernelNotEligible(
            f"seqlen {seqlen} exceeds the variant's baked kv_capacity {kv_cap}; run native decode")
    # The runtime ``kv_capacity`` request is ADVISORY: the buffers/page-table are baked at the variant's
    # ``kv_cap`` depth (a static KC in the cubin), so a larger request cannot enlarge them. It is
    # clamped implicitly -- the decode may advance up to ``kv_cap`` in the megakernel; a sequence that
    # would run past it is a native-fallback case (bucket policy), not a build error.

    instr, qlen, num_counters = _tape_to_device(meta["tape"], device)

    W = _stack_md3_weights(text, tc, device=device)

    BT = BATCH_TILE
    dt = _DTYPE
    resid = torch.zeros(2, BT, H, device=device, dtype=dt)
    x0 = dec_embed0[:, 0, :].detach().to(dt).contiguous()
    resid[0, :batch_size] = x0
    raw = torch.zeros(BT, qkv_out, device=device, dtype=dt)
    xnorm = torch.zeros(2, BT, H, device=device, dtype=dt)
    h_attn = torch.zeros(2, BT, H, device=device, dtype=dt)
    attn_out = torch.zeros(BT, H, device=device, dtype=dt)
    qkv_gelu = torch.zeros(BT, qkv_out, device=device, dtype=dt)
    tok_qv_lin = torch.zeros(BT, 2 * NH, device=device, dtype=dt)
    fc1 = torch.zeros(BT, tc.ff_dim, device=device, dtype=dt)
    topk_ids = torch.zeros(2, BT, TOPK, device=device, dtype=torch.int32)
    topk_w = torch.zeros(2, BT, TOPK, device=device, dtype=dt)
    qassign, qmax = _qmma_route_capacity(BT, top_k=TOPK, num_experts=E)
    qmma_sorted_ids = torch.empty(2, qassign, device=device, dtype=torch.int32)
    qmma_block_offsets = torch.empty(2, qmax + 2, device=device, dtype=torch.int32)
    qmma_block_expert_ids = torch.empty(2, qmax, device=device, dtype=torch.int32)
    qmma_cu_seqlens = torch.empty(2, E + 1, device=device, dtype=torch.int32)
    qmma_assignment_to_sorted = torch.empty(2, qassign, device=device, dtype=torch.int32)
    qmma_up_raw = torch.empty(2, qassign, 2 * I, device=device, dtype=dt)
    qmma_up_a_bits = torch.empty(2, BT, H, device=device, dtype=torch.uint8)
    qmma_up_a_scale = torch.empty(2, BT, device=device, dtype=torch.float32)
    qmma_down_raw = torch.empty(2, qassign, H, device=device, dtype=dt)
    qmma_down_a_bits = torch.empty(2, qassign, I, device=device, dtype=torch.uint8)
    qmma_down_a_scale = torch.empty(2, qassign, device=device, dtype=torch.float32)
    moe_act = torch.zeros(2, BT, TOPK, I, device=device, dtype=dt)
    q = torch.zeros(BT, NH, HD, device=device, dtype=dt)
    # B1 multi-CTA router cross-CTA logits scratch (2 == double-buffer par, E experts). Mirrors the dev
    # backend's ``router_logits`` arg (mkl.megakernel.session.md3._build_megakernel_run, last memref).
    router_logits = torch.zeros(2, E, device=device, dtype=torch.float32)
    # DIRECT paged-KV (seeding's ghost is finally gone from the bundle path): the megakernel reads
    # AND appends the ENGINE's paged KV pool directly -- there is NO private contiguous kv_k8/kv_v8
    # buffer and no paged->contiguous seed copy. It addresses the pool through mKptr/mVptr = device
    # int64[NL] per-layer pool base-address tables + the n_pages scalar (kv_pool_layer builds each
    # layer's [n_pages, NKV, HD] view), with the engine's global logical->physical page table.
    # Mirrors mkl.megakernel.session.md3._build_megakernel_run's paged batch branch byte-for-byte.
    n_pages = int(page_table.n_pages)
    # ENGINE CONTRACT: the engine reserves KV pages to the request's target_length at admission (the
    # scheduler's reserve()/commit), so ``page_table.page_table`` is already populated with real
    # physical pages through the row's ``capacity`` -- there
    # is NO per-build reserve/commit here. (A bench that owns its own pool must reserve it up front.)
    kv_ptr_k = torch.tensor(
        [blk.kv_cache.cache.k_cache.data_ptr() for blk in text.blocks],
        device=device, dtype=torch.int64)
    kv_ptr_v = torch.tensor(
        [blk.kv_cache.cache.v_cache.data_ptr() for blk in text.blocks],
        device=device, dtype=torch.int64)
    # FP8 (e4m3) KV pool. The production MD3 pool is torch.float8_e4m3fn with per-layer scalar k/v
    # scales (the bf16-pool gate retired); the re-emitted bundle cubin is fp8_kv=True and reads/appends
    # that pool directly -- half the KV bytes streamed per attention read + half the pool memory. Gather
    # the per-layer f32[NL] dequant scales from the SAME cache object the kv_ptr tables iterate and pack
    # them as the two TRAILING memrefs (the LAST two of the 61-memref union ABI; they follow the
    # tail-fold head block + max_events in _call_jit arg order). Byte-for-byte
    # mkl.megakernel.session.md3._build_megakernel_run's fp8 branch. A
    # non-quantized (bf16) pool is not the shipped MD3 config -- the fp8 cubin would misread it -> NATIVE
    # fallback (non-fatal), mirroring the bucket / kv_cap eligibility gates above.
    if not bool(meta.get("fp8_kv", False)):
        raise MegakernelNotEligible(
            "shipped MD3 megakernel bundle predates the fp8-KV ABI (no fp8_kv in manifest); "
            "rebuild the bundle -> run native decode")
    if not bool(getattr(text.blocks[0].kv_cache.cache, "quantized", False)):
        raise MegakernelNotEligible(
            "shipped MD3 megakernel bundle is fp8-KV only; the engine KV pool is not quantized "
            "(torch.float8_e4m3fn) -> run native decode")
    kv_scale_k = torch.stack(
        [blk.kv_cache.cache.k_scale_tensor.reshape(()) for blk in text.blocks]
    ).to(device=device, dtype=torch.float32).contiguous()
    kv_scale_v = torch.stack(
        [blk.kv_cache.cache.v_scale_tensor.reshape(()) for blk in text.blocks]
    ).to(device=device, dtype=torch.float32).contiguous()
    # Use the engine's current-position tensor directly. The VM derives kv_len as position+1 and
    # indexes the full RoPE/TAU tables in-kernel.
    if input_pos is None:
        input_pos = torch.full((batch_size,), history, device=device, dtype=torch.int32)
    # FULL resident RoPE / TAU tables, indexed in-kernel by the device position. Sliced to the baked
    # kv_cap so the runtime tensors match the AOT compile's fake-arg extents (positions reached are
    # always < kv_cap). Replaces the retired per-row cos8/sin8 + single-position tau_pos row buffers.
    cos_table, sin_table = _cossin_table(text, ROT)
    cos_table = cos_table[:kv_cap].contiguous()
    sin_table = sin_table[:kv_cap].contiguous()
    tau_table = _tau_pos_table(text)[:, :kv_cap, :].contiguous()
    o_partial = torch.empty(BT, NS, NH, HD, device=device, dtype=torch.float32)
    lse_partial = torch.empty(BT, NS, NH, device=device, dtype=torch.float32)
    ctr = torch.zeros(num_counters, device=device, dtype=torch.int32)

    # TAIL-FOLD (Stage A/B): in-kernel lm_head operands, mirroring the dev backend
    # (mkl.megakernel.session.md3._build_megakernel_run:580-594) byte-for-byte. vocab>0 (the shipped
    # MD3 variant) folds FINAL_LN + LM_HEAD + ARGMAX: the kernel writes the logits buffer the host
    # reads AND the device-argmax token slot. post_ln (2,H) f32 [0]=weight [1]=bias; the lm_head weight
    # (vocab,H) bf16 stacks like any other slab (the shard reads it with Int64 strides); the bias
    # (vocab,) f32; logits (BATCH_TILE,vocab) f32; token (BATCH_TILE,) int32. None when vocab==0 (host
    # lm_head) -> the tail memrefs are simply not appended (the base 54-memref ABI).
    vocab = int(meta.get("vocab") or 0)
    post_ln_t = lm_head_w = lm_head_b = logits_buf = token_buf = None
    if vocab > 0:
        post_ln_t = torch.stack([
            text.post_ln.weight.detach().float(),
            text.post_ln.bias.detach().float()], dim=0).contiguous()
        lm_head_w = text.lm_head.weight.detach().to(dt).contiguous()
        lm_head_b = text.lm_head.bias.detach().float().contiguous()
        logits_buf = torch.zeros(BT, vocab, device=device, dtype=torch.float32)
        token_buf = torch.zeros(BT, device=device, dtype=torch.int32)

    # Complete named bindings for the compiler-generated AOT ABI. Full RoPE/TAU tables and optional
    # folded-head / FP8-scale operands are ordinary declarations; no positional convention lives here.
    bindings = {
        "mResidual": resid, "mGamma": W["gamma"], "mBeta": W["beta"],
        "mWqkv": W["Wqkv"], "mQkvBias": W["qkv_bias"], "mZeroBias": W["zero_bias"],
        "mRaw": raw, "mXnorm": xnorm, "mHattn": h_attn, "mAttnOut": attn_out,
        "mWqwv": W["Wqwv"], "mQkvGelu": qkv_gelu, "mTokQvLin": tok_qv_lin,
        "mTauPos": tau_table, "mWfc1": W["Wfc1"], "mB1": W["b1"], "mFc1": fc1,
        "mWo": W["Wo"], "mWoBias": W["o_bias"], "mWfc2": W["Wfc2"], "mB2": W["b2"],
        "mGateW": W["gate_w"], "mGateB": W["gate_b"], "mTopkIds": topk_ids,
        "mTopkW": topk_w, "mUpW": W["up_w"], "mUpScale": W["up_scale"],
        "mDownW": W["down_w"], "mDownScale": W["down_scale"], "mMoeAct": moe_act,
        "mCos": cos_table, "mSin": sin_table, "mInstr": instr, "mQlen": qlen,
        "mCtr": ctr, "mQ": q, "mKptr": kv_ptr_k, "mVptr": kv_ptr_v,
        "n_pages": n_pages, "mPageTable": page_table.page_table, "mBatchIdx": batch_idx,
        "mInputPos": input_pos, "mO_partial": o_partial,
        "mLSE_partial": lse_partial, "kv_len": kv_cap, "active_batch": batch_size,
        "mQmmaSortedIds": qmma_sorted_ids, "mQmmaBlockOffsets": qmma_block_offsets,
        "mQmmaBlockExpertIds": qmma_block_expert_ids, "mQmmaCuSeqlens": qmma_cu_seqlens,
        "mQmmaAssignmentToSorted": qmma_assignment_to_sorted,
        "mQmmaUpRaw": qmma_up_raw, "mQmmaUpABits": qmma_up_a_bits,
        "mQmmaUpAScale": qmma_up_a_scale, "mQmmaDownRaw": qmma_down_raw,
        "mQmmaDownABits": qmma_down_a_bits, "mQmmaDownAScale": qmma_down_a_scale,
        "mRouterLogits": router_logits, "max_events": 0,
        "mKScale": kv_scale_k, "mVScale": kv_scale_v,
    }
    if vocab > 0:
        bindings.update({
            "mPostLn": post_ln_t, "mWlmHead": lm_head_w,
            "mLmHeadBias": lm_head_b, "mLogits": logits_buf, "mToken": token_buf,
        })
    stream_c = ctypes.c_void_p(0)

    return _BundleSession(
        bundle=bundle, bindings=bindings, arg_abi=meta.get("arg_abi"),
        memref_abi=meta.get("memref_abi"), stream_c=stream_c,
        device_index=device_index, num_ctas=int(num_ctas),
        batch_size=batch_size, n_layers=NL, hidden=H, resid=resid, ctr=ctr, x0=x0,
        input_pos=input_pos,
        page_table=page_table,
        batch_idx=batch_idx, kv_cap=kv_cap,
        n_kv_heads=NKV, head_dim=HD, logits=logits_buf, token=token_buf)


def _build_md2_decode_session(text, tc, dec_embed0, page_table, batch_idx, *, input_pos=None,
                              compiler_kind: str, batch_bucket: int,
                              seqlen: int, num_ctas: int, config=None,
                              kv_capacity: Optional[int] = None, arch: Optional[str] = None):
    """Build dense MD2 on the same packed-AOT and direct-paged-KV substrate as MD3."""
    if dec_embed0 is None:
        device = batch_idx.device
        dec_embed0 = torch.zeros(int(batch_bucket), 1, tc.dim, device=device, dtype=_DTYPE)
    else:
        device = dec_embed0.device
    device_index = int(device.index or 0)
    bundle, meta = resolve_bundle(
        compiler_kind, tc, int(num_ctas), config, arch,
        static_extent_bindings={"active_batch": int(batch_bucket)})
    if bundle is None or meta is None:
        raise MegakernelNotEligible("no shipped whole-model megakernel bundle for this device")

    baked = meta["spec"]
    H, NH, NKV = tc.dim, tc.n_heads, tc.n_kv_heads
    HD = H // NH
    ROT = H // (2 * NH)
    NL, FF = tc.n_layers, tc.ff_dim
    qkv_out = H + 2 * NKV * HD
    BT = int(baked["batch_tile"])
    NS = int(baked["num_splits"])
    kv_cap = int(baked["kv_capacity"])
    batch_size = int(batch_bucket)
    history = int(seqlen) - 1
    if batch_size > BT:
        raise MegakernelNotEligible(
            f"batch bucket {batch_size} exceeds the bundle tile {BT}; run native decode")
    if int(seqlen) > kv_cap:
        raise MegakernelNotEligible(
            f"seqlen {seqlen} exceeds the variant's baked kv_capacity {kv_cap}; run native decode")

    instr, qlen, num_counters = _tape_to_device(meta["tape"], device)
    W = _stack_md2_weights(text, device=device)
    dt = _DTYPE
    resid = torch.zeros(2, BT, H, device=device, dtype=dt)
    x0 = torch.zeros(BT, H, device=device, dtype=dt)
    x0[:batch_size].copy_(dec_embed0[:batch_size, 0, :].detach().to(dt))
    resid[0].copy_(x0)
    raw = torch.zeros(BT, qkv_out, device=device, dtype=dt)
    xnorm = torch.zeros(BT, H, device=device, dtype=dt)
    fc1 = torch.zeros(BT, FF, device=device, dtype=dt)
    attn_out = torch.zeros(BT, H, device=device, dtype=dt)
    h_attn = torch.zeros(BT, H, device=device, dtype=torch.float32)
    q = torch.zeros(BT, NH, HD, device=device, dtype=dt)
    cos_table, sin_table = _cossin_table(text, ROT)
    cos_table = cos_table[:kv_cap].contiguous()
    sin_table = sin_table[:kv_cap].contiguous()

    blocks = text["blocks"]
    if bool(getattr(blocks[0].kv_cache.cache, "quantized", False)):
        raise MegakernelNotEligible(
            "the shipped MD2 bundle expects bf16 KV, but the engine pool is quantized")
    n_pages = int(page_table.n_pages)
    kv_ptr_k = torch.tensor(
        [block.kv_cache.cache.k_cache.data_ptr() for block in blocks],
        device=device, dtype=torch.int64)
    kv_ptr_v = torch.tensor(
        [block.kv_cache.cache.v_cache.data_ptr() for block in blocks],
        device=device, dtype=torch.int64)
    if input_pos is None:
        input_pos = torch.full((batch_size,), history, device=device, dtype=torch.int32)
    o_partial = torch.empty(BT, NS, NH, HD, device=device, dtype=torch.float32)
    lse_partial = torch.empty(BT, NS, NH, device=device, dtype=torch.float32)
    ctr = torch.zeros(num_counters, device=device, dtype=torch.int32)

    bindings = {
        "mResidual": resid, "mGamma": W["gamma"], "mBeta": W["beta"],
        "mWqkv": W["Wqkv"], "mQkvBias": W["qkv_bias"], "mRaw": raw,
        "mXnorm": xnorm, "mWfc1": W["Wfc1"], "mB1": W["b1"], "mFc1": fc1,
        "mWo": W["Wo"], "mWoBias": W["o_bias"], "mWfc2": W["Wfc2"],
        "mB2": W["b2"], "mAttnOut": attn_out, "mHattn": h_attn,
        "mCos": cos_table, "mSin": sin_table, "mInstr": instr, "mQlen": qlen,
        "mCtr": ctr, "mQ": q, "mKptr": kv_ptr_k, "mVptr": kv_ptr_v,
        "n_pages": n_pages, "mPageTable": page_table.page_table, "mBatchIdx": batch_idx,
        "mInputPos": input_pos, "mO_partial": o_partial,
        "mLSE_partial": lse_partial, "kv_len": kv_cap, "active_batch": batch_size,
        "max_events": 0, "lora_fc1_tiles": 0, "lora_fc2_tiles": 0, "prof_slots": 8,
    }
    return _BundleSession(
        bundle=bundle, bindings=bindings, arg_abi=meta.get("arg_abi"),
        memref_abi=meta.get("memref_abi"),
        stream_c=ctypes.c_void_p(0), device_index=device_index, num_ctas=int(num_ctas),
        batch_size=batch_size, n_layers=NL, hidden=H,
        resid=resid, ctr=ctr, x0=x0, input_pos=input_pos,
        page_table=page_table, batch_idx=batch_idx,
        kv_cap=kv_cap, n_kv_heads=NKV, head_dim=HD)


_SESSION_BUILDERS = {
    "moondream2": _build_md2_decode_session,
    "moondream3": _build_md3_decode_session,
}


def build_decode_session(
    model_kind, text, tc, dec_embed0, page_table, batch_idx, *, compiler_kind, **kwargs,
):
    """Build a model ABI session selected through its compiler registration and exact identity."""
    try:
        builder = _SESSION_BUILDERS[model_kind]
    except KeyError as exc:
        raise MegakernelNotEligible(f"no whole-model bundle backend for {model_kind!r}") from exc
    return builder(
        text, tc, dec_embed0, page_table, batch_idx,
        compiler_kind=compiler_kind, **kwargs,
    )


# ======================================================================================
# Build-time artifact emit (dev / source install). Imports mkl; NEVER on the runtime path.
# ======================================================================================
def build_bundle_artifacts(
    compiler_kind: str,
    tc,
    num_ctas: int,
    arch: Optional[str] = None,
    *,
    static_extent_bindings=None,
) -> dict:
    """JIT-build the AOT ``.so`` and write the tape/geometry sidecar so a masked-mkl host can
    consume it. Uses mkl's compile target (build-time dep only). Runtime extents select the same
    compiler-catalog request domain as ``resolve_bundle``. Returns the sidecar dict."""
    from mkl.megakernel.integration import (
        artifact_variant_key,
        iter_model_specs,
        get_tape,
        manifest_variant,
    )

    arch = arch or get_cuda_arch()
    specs = tuple(iter_model_specs(
        num_sms=int(num_ctas),
        gpu=torch.cuda.get_device_name(torch.cuda.current_device()),
    ))
    records = tuple({
        "arch": str(arch),
        # Select the semantic compiler spec before materializing its tape. A tape compile can be
        # expensive; only the selected artifact needs that exact ABI identity.
        "variant_key": str(spec.variant_key),
        "request_extent_bindings": spec.request_extents,
        "spec": spec.serialize(),
    } for spec in specs)
    selected = _select_requested_spec(
        records,
        arch=str(arch),
        constraints=_runtime_spec_constraints(
            compiler_kind, tc, int(num_ctas), None),
        static_extent_bindings=static_extent_bindings,
    )
    if selected is None:
        raise RuntimeError(
            f"no mkl {compiler_kind} whole-model spec matches this text config "
            f"(num_sms={num_ctas}, arch={arch})")
    spec = next(
        candidate for candidate in specs
        if candidate.variant_key == selected["variant_key"])
    tape = get_tape(spec)
    key = artifact_variant_key(spec, tape=tape)
    selected = dict(selected, variant_key=key)

    family = _make_family()
    bundle = family.resolve(
        _VariantKey(key, int(num_ctas)), arch)
    if bundle is None:
        raise RuntimeError(f"failed to build/resolve AOT bundle for {key} on {arch}")

    instr = tape.instr.contiguous()
    qlen = tape.qlen.contiguous()
    var = dict(manifest_variant(spec))
    aot_sidecar = family.bundle_dir / f"{key}_{arch}.aot.json"
    try:
        aot_meta = json.loads(aot_sidecar.read_text())
        var["arg_abi"] = aot_meta["arg_abi"]
        var["memref_abi"] = aot_meta["memref_abi"]
    except (OSError, ValueError, KeyError) as exc:
        raise RuntimeError(
            f"JIT bundle {key!r} did not emit its named AOT argument ABI"
        ) from exc
    sidecar = dict(var)
    sidecar["selection_catalog_schema"] = _SELECTION_CATALOG_SCHEMA
    sidecar["selection_catalog"] = [selected]
    sidecar["tape"] = {
        "instr_b64": base64.b64encode(instr.numpy().tobytes()).decode("ascii"),
        "qlen_b64": base64.b64encode(qlen.numpy().tobytes()).decode("ascii"),
        "instr_shape": list(instr.shape), "qlen_shape": list(qlen.shape),
        "max_qlen": int(tape.max_qlen), "fields": int(tape.fields),
        "num_ctas": int(tape.num_ctas), "num_counters": int(tape.num_counters),
    }
    sc_path = _sidecar_path(family.bundle_dir, key, arch)
    sc_path.parent.mkdir(parents=True, exist_ok=True)
    sc_path.write_text(json.dumps(sidecar))
    return {"variant_key": key, "arch": arch, "sidecar": str(sc_path),
            "arg_kinds": list(bundle.arg_kinds)}


__all__ = [
    "WHOLE_MODEL_FAMILY", "MegakernelNotEligible", "build_decode_session",
    "resolve_bundle", "bundle_available", "shipped_bundle_available",
    "build_bundle_artifacts",
]
